/**
 * @event
 * @name scwin.btn_fnSearchInit_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnSearchInit_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnSearchInit(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst70410.btn_fnSearchInit_onclick' }); }
};

